#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_double_array_malloc_failure(void) {
    // Setup: create a valid stack with some capacity
    DArrayStack *stack = create_stack(5);
    TEST_ASSERT_NOT_NULL(stack);
    // Push some elements to ensure top is set
    int push_result = push(stack, 10);
    TEST_ASSERT_EQUAL_INT(0, push_result); // top becomes 0

    // Now we need to fail the malloc inside double_array.
    // The stack creation involved 2 allocations (struct + array).
    // So we need to fail the 3rd allocation (the malloc for temp).
    malloc_fail_after(2);

    // Test: call double_array with valid inputs, expecting malloc failure
    DArrayStack *result = double_array(stack, 5);

    // Assertions: should return NULL due to malloc failure
    TEST_ASSERT_NULL(result);
    // The original stack should still be intact (not freed) because the function returns NULL early.
    TEST_ASSERT_NOT_NULL(stack);
    TEST_ASSERT_EQUAL_INT(5, stack->capacity);
    TEST_ASSERT_EQUAL_INT(0, stack->top);
    TEST_ASSERT_NOT_NULL(stack->arrPtr);

    // Cleanup
    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_double_array_malloc_failure);
    return UNITY_END();
}

