void helper_assert_stack_to_string(DArrayStack *stack, const char *expected_string) {
    int buffer_size = 256;
    char *buffer = malloc(buffer_size * sizeof(char));
    int result = stack_to_string(stack, buffer, buffer_size);
    assert(result != -1);
    assert(strcmp(buffer, expected_string) == 0);
    free(buffer);
