// Creates a stack and pushes an array of values onto it
DArrayStack *helper_create_stack_with_values(int *values, int size, int initial_capacity) {
    DArrayStack *stack = create_stack(initial_capacity);
    if (stack == NULL) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        push(stack, values[i]);
    }
    return stack;
}

