    DArrayStack *stack = create_stack(initial_capacity);
    if (stack == NULL) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        int value = min_value + rand() % (max_value - min_value + 1);
        push(stack, value);
    }
    return stack;
